select * from (values (10, 1), (30, 3)) as t (x, y)
union all
select * from (values (20, 2)) as t (x, y)
) as t
where x + y > 30;

select * from emp
where NOT EXISTS (
  select * from emp ee where ee.job = emp.job AND ee.sal=34);

select * from emp
where NOT EXISTS (
  select 1 from emp ee where ee.job = emp.job AND ee.sal = 34);

select * from emp where exists (
  select 1 from dept
  where dept.name = emp.job
    and dept.deptno < emp.empno
);
